package edu.ise.seatplan;
import org.springframework.stereotype.Service;
import java.util.*;

@Service class AllocationService {
 final RoomRepository rooms; final ExamRepository exams;
 AllocationService(RoomRepository r,ExamRepository e){rooms=r;exams=e;}
 List<Seat> seats(List<Long> ids)throws Exception {return seats(ids,false);}
 List<Seat> seats(List<Long> ids,boolean mixed)throws Exception {List<Seat> out=new ArrayList<>();for(Room r:rooms.findAllById(ids)){Layout l=effectiveLayout(r,mixed);for(int c=0;c<l.columns().size();c++){List<Bench> bs=l.columns().get(c).benches();int maxPositions=bs.stream().mapToInt(Bench::positions).max().orElse(0);for(int p=1;p<=maxPositions;p++)for(int b=0;b<bs.size();b++)if(p<=bs.get(b).positions()&&!bs.get(b).blocked().contains(p))out.add(new Seat(r.id,r.name,"C"+(c+1),b+1,p));}}return out;}
 Layout effectiveLayout(Room room,boolean mixed)throws Exception {Layout saved=Json.layout(room.layoutJson);boolean regular="DEFAULT".equalsIgnoreCase(room.mode);List<Column> columns=saved.columns().stream().map(c->new Column(c.benches().stream().map(b->{int positions=regular?(mixed?3:2):(mixed?b.positions():(b.singlePositions()==null?b.positions():b.singlePositions()));return new Bench(positions,b.blocked().stream().filter(p->p<=positions).toList(),b.singlePositions());}).toList())).toList();return new Layout(columns,saved.orientation());}
 Map<String,Object> suggestRanges(List<String> usns,List<Long> ids)throws Exception {
  return suggestRanges(usns,ids,List.of(),false);
 }
 Map<String,Object> suggestRanges(List<String> usns,List<Long> ids,List<RoomRange> previous)throws Exception {
  return suggestRanges(usns,ids,previous,false);
 }
 Map<String,Object> suggestRanges(List<String> usns,List<Long> ids,List<RoomRange> previous,boolean mixed)throws Exception {
  Map<Long,Integer> capacity=new LinkedHashMap<>();for(Long id:ids)capacity.put(id,0);for(Seat seat:seats(ids,mixed))capacity.computeIfPresent(seat.roomId(),(k,v)->v+1);
  int totalCapacity=capacity.values().stream().mapToInt(Integer::intValue).sum();int toAssign=Math.min(usns.size(),totalCapacity);
  List<String> normalized=usns.stream().map(this::normalize).sorted(String.CASE_INSENSITIVE_ORDER).toList();
  Map<String,List<String>> cohorts=new TreeMap<>();for(String usn:normalized){java.util.regex.Matcher m=java.util.regex.Pattern.compile("^(.+?)([0-9]+)$").matcher(usn);String cohort=m.matches()?m.group(1):"~OTHER";cohorts.computeIfAbsent(cohort,k->new ArrayList<>()).add(usn);}
  List<RoomRange> ranges=List.of();
  for(int attempt=0;attempt<16&&(ranges.isEmpty()||sameRoomRanges(ranges,previous));attempt++){
   List<Long> tieOrder=new ArrayList<>(ids);Collections.shuffle(tieOrder);Map<Long,Integer> target=balancedTargets(toAssign,capacity,tieOrder);Map<Long,Integer> placed=new LinkedHashMap<>();for(Long id:ids)placed.put(id,0);
   List<String> cohortOrder=new ArrayList<>(cohorts.keySet());Collections.shuffle(cohortOrder);List<RoomRange> proposal=new ArrayList<>();
   for(String cohort:cohortOrder){List<String> students=cohorts.get(cohort);Map<Long,Integer> counts=new LinkedHashMap<>();for(Long id:ids)counts.put(id,0);
    for(int i=0;i<students.size()&&placed.values().stream().mapToInt(Integer::intValue).sum()<toAssign;i++){
     int maxDeficit=ids.stream().mapToInt(id->target.get(id)-placed.get(id)).max().orElse(0);if(maxDeficit<=0)break;
     List<Long> choices=ids.stream().filter(id->target.get(id)-placed.get(id)==maxDeficit).collect(java.util.stream.Collectors.toCollection(ArrayList::new));Long room=choices.get(java.util.concurrent.ThreadLocalRandom.current().nextInt(choices.size()));counts.compute(room,(k,v)->v+1);placed.compute(room,(k,v)->v+1);
    }
    List<Long> roomOrder=new ArrayList<>(ids);Collections.shuffle(roomOrder);int cursor=0;for(Long room:roomOrder){int count=counts.get(room);if(count>0){proposal.add(new RoomRange(room,students.get(cursor),students.get(cursor+count-1)));cursor+=count;}}
   }
   ranges=proposal;
  }
  return Map.of("ranges",ranges,"capacity",totalCapacity,"assigned",Math.min(usns.size(),totalCapacity),"unassigned",Math.max(0,usns.size()-totalCapacity));
 }
 private Map<Long,Integer> balancedTargets(int count,Map<Long,Integer> capacity,List<Long> tieOrder){
  Map<Long,Integer> target=new LinkedHashMap<>();int total=capacity.values().stream().mapToInt(Integer::intValue).sum();if(total==0){for(Long id:capacity.keySet())target.put(id,0);return target;}
  int placed=0;Map<Long,Double> remainder=new HashMap<>();for(Long id:capacity.keySet()){double exact=(double)count*capacity.get(id)/total;int base=(int)Math.floor(exact);target.put(id,base);placed+=base;remainder.put(id,exact-base);}
  List<Long> order=new ArrayList<>(tieOrder);order.sort(Comparator.comparingDouble((Long id)->remainder.get(id)).reversed());for(Long id:order)if(placed<count&&target.get(id)<capacity.get(id)){target.compute(id,(k,v)->v+1);placed++;}
  return target;
 }
 private boolean sameRoomRanges(List<RoomRange> a,List<RoomRange> b){if(b==null||b.isEmpty())return false;Comparator<RoomRange> order=Comparator.comparing(RoomRange::roomId).thenComparing(RoomRange::startUsn);return a.stream().sorted(order).toList().equals(b.stream().sorted(order).toList());
 }
 List<Assignment> generateByRanges(List<String> usns,List<Long> ids,List<RoomRange> rules)throws Exception {
  return generateByRanges(usns,ids,rules,Map.of(),"SINGLE","B_A_B","","");
 }
 List<Assignment> generateByRanges(List<String> usns,List<Long> ids,List<RoomRange> rules,Map<String,String> groups,String seatingMode,String mixPattern,String semesterA,String semesterB)throws Exception {
  boolean mixed="MIXED".equals(seatingMode);List<Seat> all=seats(ids,mixed);Map<Long,List<Seat>> byRoom=new LinkedHashMap<>();for(Long id:ids)byRoom.put(id,new ArrayList<>());for(Seat seat:all)byRoom.computeIfAbsent(seat.roomId(),k->new ArrayList<>()).add(seat);
  if(rules==null||rules.isEmpty())throw new IllegalArgumentException("Add at least one room USN range before generating the arrangement.");
  Map<Long,List<String>> assigned=new LinkedHashMap<>();for(Long id:ids)assigned.put(id,new ArrayList<>());
  Map<RoomRange,Integer> matched=new LinkedHashMap<>();for(RoomRange rule:rules){String start=normalize(rule.startUsn()),end=normalize(rule.endUsn());if(!byRoom.containsKey(rule.roomId()))throw new IllegalArgumentException("A range refers to a room that is not selected.");if(!start.matches("[A-Z0-9]{8,20}")||!end.matches("[A-Z0-9]{8,20}")||start.compareTo(end)>0)throw new IllegalArgumentException("Each range must have valid 8–20 character USN endpoints with the first USN no greater than the last.");matched.put(rule,0);}
  Set<String> seen=new HashSet<>();for(String original:usns){String usn=normalize(original);if(!seen.add(usn))throw new IllegalArgumentException("Duplicate eligible USN: "+usn);List<RoomRange> hits=rules.stream().filter(rule->{String start=normalize(rule.startUsn()),end=normalize(rule.endUsn());return usn.compareTo(start)>=0&&usn.compareTo(end)<=0;}).toList();if(hits.isEmpty())throw new IllegalArgumentException("No room range includes eligible USN "+usn+". Update the ranges or explicitly exclude this student.");if(hits.size()>1)throw new IllegalArgumentException("USN "+usn+" matches more than one room range. Remove overlapping ranges.");RoomRange hit=hits.get(0);assigned.get(hit.roomId()).add(usn);matched.put(hit,matched.get(hit)+1);}
  for(var entry:matched.entrySet())if(entry.getValue()==0)throw new IllegalArgumentException("Range "+normalize(entry.getKey().startUsn())+"–"+normalize(entry.getKey().endUsn())+" contains no eligible students. Check or remove it.");
  Set<String> tripleBenchKeys=new HashSet<>(),pairBenchKeys=new HashSet<>();if(mixed){if(!"A_B_A".equals(mixPattern)&&!"B_A_B".equals(mixPattern))throw new IllegalArgumentException("Choose one of the two mixed-semester bench patterns.");for(Room room:rooms.findAllById(ids)){Layout layout=effectiveLayout(room,true);for(int c=0;c<layout.columns().size();c++)for(int b=0;b<layout.columns().get(c).benches().size();b++){Bench bench=layout.columns().get(c).benches().get(b);int available=bench.positions()-bench.blocked().size();if(available==3)tripleBenchKeys.add(room.id+"|C"+(c+1)+"|"+(b+1));if("SPECIAL".equalsIgnoreCase(room.mode)&&available==2)pairBenchKeys.add(room.id+"|C"+(c+1)+"|"+(b+1));}}}
  List<Assignment> result=new ArrayList<>();for(int roomIndex=0;roomIndex<ids.size();roomIndex++){Long id=ids.get(roomIndex);List<String> students=assigned.get(id);List<Seat> roomSeats=byRoom.get(id);if(students.size()>roomSeats.size())throw new IllegalArgumentException("Room "+(roomSeats.isEmpty()?id:roomSeats.get(0).room())+" has "+students.size()+" students in its ranges but only "+roomSeats.size()+" available seats.");students.sort(String.CASE_INSENSITIVE_ORDER);if(mixed){result.addAll(assignMixed(students,roomSeats,groups,mixPattern,semesterA,semesterB,tripleBenchKeys,pairBenchKeys,roomIndex));}else for(int i=0;i<students.size();i++)result.add(new Assignment(students.get(i),roomSeats.get(i)));}
  return result;
 }
 private List<Assignment> assignMixed(List<String> students,List<Seat> roomSeats,Map<String,String> groups,String pattern,String semesterA,String semesterB,Set<String> tripleBenchKeys,Set<String> pairBenchKeys,int roomIndex){
  Long roomId=roomSeats.isEmpty()?null:roomSeats.get(0).roomId();Map<String,List<Seat>> benches=new LinkedHashMap<>();for(Seat seat:roomSeats)benches.computeIfAbsent(seat.column()+"|"+seat.bench(),k->new ArrayList<>()).add(seat);benches.values().forEach(list->list.sort(Comparator.comparingInt(Seat::position)));
  List<String> a=students.stream().filter(u->semesterA.equals(groups.get(u))).sorted(String.CASE_INSENSITIVE_ORDER).toList(),b=students.stream().filter(u->semesterB.equals(groups.get(u))).sorted(String.CASE_INSENSITIVE_ORDER).toList();if(a.size()+b.size()!=students.size())throw new IllegalArgumentException("Every ranged student in room "+roomSeats.get(0).room()+" must map to one of the two selected semesters.");int[] cursor={0,0};int tripleIndex=0,pairIndex=0;int remainingPairs=Math.min((int)benches.keySet().stream().filter(k->pairBenchKeys.contains(roomId+"|"+k)).count(),Math.min(a.size(),b.size()));List<Assignment> result=new ArrayList<>();
  for(var entry:benches.entrySet()){
   String key=entry.getKey();List<Seat> bench=entry.getValue();boolean triple=tripleBenchKeys.contains(roomId+"|"+key)&&bench.size()==3;boolean pair=pairBenchKeys.contains(roomId+"|"+key)&&bench.size()==2;
   if(triple){int limitA=a.size()-remainingPairs,limitB=b.size()-remainingPairs;int availableA=Math.max(0,limitA-cursor[0]),availableB=Math.max(0,limitB-cursor[1]);int total=availableA+availableB;int toPlace=Math.min(3,total);int aSeats=total==0?0:(int)Math.round((double)toPlace*availableA/total);aSeats=Math.max(Math.max(0,toPlace-availableB),Math.min(Math.min(toPlace,availableA),aSeats));int bSeats=toPlace-aSeats;List<Boolean> cohortA;if(tripleIndex==0&&toPlace==3&&"A_B_A".equals(pattern)&&availableA>=2&&availableB>=1){aSeats=2;bSeats=1;cohortA=List.of(true,false,true);}else if(tripleIndex==0&&toPlace==3&&"B_A_B".equals(pattern)&&availableA>=1&&availableB>=2){aSeats=1;bSeats=2;cohortA=List.of(false,true,false);}else{boolean aMajority=aSeats>=bSeats;boolean startMajority=(tripleIndex+roomIndex+("A_B_A".equals(pattern)?1:0))%2==0;cohortA=triplePattern(aSeats,bSeats,aMajority,startMajority);}for(int i=0;i<cohortA.size();i++){String usn=cohortA.get(i)?(cursor[0]<limitA?a.get(cursor[0]++):null):(cursor[1]<limitB?b.get(cursor[1]++):null);if(usn!=null)result.add(new Assignment(usn,bench.get(i)));}tripleIndex++;
   }else if(pair){if(remainingPairs>0&&cursor[0]<a.size()&&cursor[1]<b.size()){boolean aFirst=(pairIndex+roomIndex)%2==0;String first=aFirst?a.get(cursor[0]++):b.get(cursor[1]++),second=aFirst?b.get(cursor[1]++):a.get(cursor[0]++);result.add(new Assignment(first,bench.get(0)));result.add(new Assignment(second,bench.get(1)));remainingPairs--;pairIndex++;}else{for(Seat seat:bench){String usn=nextOrdered(a,b,cursor,a.size(),b.size());if(usn==null)break;result.add(new Assignment(usn,seat));}}
   }else for(Seat seat:bench){String usn=nextOrdered(a,b,cursor,a.size()-remainingPairs,b.size()-remainingPairs);if(usn==null)break;result.add(new Assignment(usn,seat));}
  }
  if(cursor[0]<a.size()||cursor[1]<b.size())throw new IllegalArgumentException("Room "+(roomSeats.isEmpty()?roomId:roomSeats.get(0).room())+" has "+(a.size()-cursor[0])+" "+semesterA+" and "+(b.size()-cursor[1])+" "+semesterB+" students that exceed its available seats.");return result;
 }
 private List<Boolean> triplePattern(int aCount,int bCount,boolean aMajority,boolean startMajority){List<Boolean> pattern=new ArrayList<>();boolean majorityIsA=aMajority;int major=Math.max(aCount,bCount),minor=Math.min(aCount,bCount);boolean startA=startMajority?majorityIsA:!majorityIsA;for(int i=0;i<major+minor;i++){boolean useA;if(major==minor)useA=(i%2==0)==startA;else if(i%2==0&&i<minor*2)useA=startA;else if(i%2==1&&i<minor*2)useA=!startA;else useA=majorityIsA;pattern.add(useA);}return pattern;}
 private String nextOrdered(List<String> a,List<String> b,int[] cursor,int limitA,int limitB){if(cursor[0]>=limitA)return cursor[1]<limitB?b.get(cursor[1]++):null;if(cursor[1]>=limitB)return a.get(cursor[0]++);if(a.get(cursor[0]).compareToIgnoreCase(b.get(cursor[1]))<=0)return a.get(cursor[0]++);return b.get(cursor[1]++);} private String normalize(String usn){return usn==null?"":usn.trim().toUpperCase(Locale.ROOT);}
 void validate(List<Assignment>a,List<String> eligible,List<Long> ids)throws Exception {validate(a,eligible,ids,false);}
 void validate(List<Assignment>a,List<String> eligible,List<Long> ids,boolean mixed)throws Exception {Set<String> seen=new HashSet<>();Set<Seat> used=new HashSet<>();Set<Seat> valid=new HashSet<>(seats(ids,mixed));for(Assignment x:a){if(!seen.add(x.usn()))throw new IllegalArgumentException("Duplicate student assignment: "+x.usn());if(!valid.contains(x.seat()))throw new IllegalArgumentException("Invalid or blocked seat for "+x.usn());if(!used.add(x.seat()))throw new IllegalArgumentException("Seat "+x.seat().room()+" "+x.seat().column()+" bench "+x.seat().bench()+" position "+x.seat().position()+" is assigned more than once.");}if(!seen.equals(new HashSet<>(eligible)))throw new IllegalArgumentException("Every eligible student must appear exactly once.");}
 void validateMixedPairing(List<Assignment> assignments,Map<String,String> groups,List<Long> ids)throws Exception {Map<String,Long> semesterCounts=groups.values().stream().filter(Objects::nonNull).distinct().collect(java.util.stream.Collectors.toMap(x->x,x->0L,(a,b)->a,LinkedHashMap::new));if(semesterCounts.size()!=2)throw new IllegalArgumentException("Mixed seating validation requires exactly two semester labels.");String semesterA=semesterCounts.keySet().iterator().next(),semesterB=semesterCounts.keySet().stream().skip(1).findFirst().orElseThrow();Map<String,List<Assignment>> byBench=new HashMap<>();for(Assignment assignment:assignments)byBench.computeIfAbsent(assignment.seat().roomId()+"|"+assignment.seat().column()+"|"+assignment.seat().bench(),k->new ArrayList<>()).add(assignment);for(Room room:rooms.findAllById(ids))if("SPECIAL".equalsIgnoreCase(room.mode)){Layout layout=effectiveLayout(room,true);List<String> pairBenchKeys=new ArrayList<>();for(int c=0;c<layout.columns().size();c++)for(int b=0;b<layout.columns().get(c).benches().size();b++){Bench bench=layout.columns().get(c).benches().get(b);if(bench.positions()-bench.blocked().size()==2)pairBenchKeys.add(room.id+"|C"+(c+1)+"|"+(b+1));}long roomA=assignments.stream().filter(a->a.seat().roomId().equals(room.id)&&semesterA.equals(groups.get(a.usn()))).count(),roomB=assignments.stream().filter(a->a.seat().roomId().equals(room.id)&&semesterB.equals(groups.get(a.usn()))).count();long expected=Math.min(pairBenchKeys.size(),Math.min(roomA,roomB)),cross=0;for(String key:pairBenchKeys){List<Assignment> occupants=byBench.getOrDefault(key,List.of());if(occupants.size()==2){String first=groups.get(occupants.get(0).usn()),second=groups.get(occupants.get(1).usn());if(first==null||second==null||(!semesterA.equals(first)&&!semesterB.equals(first))||(!semesterA.equals(second)&&!semesterB.equals(second)))throw new IllegalArgumentException("Room "+room.name+" has a two-position bench with a student missing a valid semester label.");if(!first.equals(second))cross++;}}if(cross<expected)throw new IllegalArgumentException("Room "+room.name+" has "+roomA+" "+semesterA+" and "+roomB+" "+semesterB+" students; at least "+expected+" cross-semester pairs are possible on its two-position benches, but only "+cross+" are assigned. Same-semester fallback pairs are allowed after cross-semester pairs are maximized.");}}
 void validateRanges(List<Assignment> assignments,List<RoomRange> rules){if(rules==null||rules.isEmpty())return;for(Assignment a:assignments){String u=normalize(a.usn());List<RoomRange> matches=rules.stream().filter(r->u.compareTo(normalize(r.startUsn()))>=0&&u.compareTo(normalize(r.endUsn()))<=0).toList();if(matches.size()!=1||!Objects.equals(matches.get(0).roomId(),a.seat().roomId()))throw new IllegalArgumentException("USN "+u+" must remain in its configured room range. Change the ranges before moving this student to another room.");}}
}
